def calculate_multiples(n, m):
    multiples = []
    for i in range(1, m+1):
        if i % n == 0:
            multiples.append(i)
    return multiples

n = int(input("Enter the value of n: "))
m = int(input("Enter the value of m: "))

result = calculate_multiples(n, m)
print(f"Multiples of {n} up to {m}: {result}")
